import collections


def transform(grid):
    """Two same-shaped blocks separated by a constant full row/column whose color
    appears nowhere else. Output has the blocks' shape: 3 where the two
    corresponding cells both equal the color shared by the two blocks, otherwise
    that shared color. No transposition is applied."""
    H, W = len(grid), len(grid[0])
    allc = collections.Counter(c for r in grid for c in r)
    sep = []
    for j in range(W):
        col = {grid[i][j] for i in range(H)}
        if len(col) == 1 and allc[next(iter(col))] == H:
            sep.append((j, 'col'))
    for i in range(H):
        row = set(grid[i])
        if len(row) == 1 and allc[next(iter(row))] == W:
            sep.append((i, 'row'))
    idx, typ = min(sep, key=lambda t: abs(t[0] - ((H if t[1] == 'row' else W) / 2)))
    if typ == 'col':
        A, B = [r[:idx] for r in grid], [r[idx + 1:] for r in grid]
    else:
        A, B = grid[:idx], grid[idx + 1:]
    ca = collections.Counter(c for r in A for c in r)
    cb = collections.Counter(c for r in B for c in r)
    s = sorted(set(ca) & set(cb), key=lambda c: -(ca[c] + cb[c]))[0]
    return [[3 if A[i][j] == s and B[i][j] == s else s for j in range(len(A[0]))] for i in range(len(A))]

import collections

def transform(grid):
    h, w = len(grid), len(grid[0])
    A = B = None; orient = None
    for i in range(h):
        if len(set(grid[i])) == 1:
            a = [r[:w] for r in grid[:i]]; b = [r[:w] for r in grid[i+1:]]
            if a and b and len(a) == len(b):
                A, B, orient = a, b, 'row'; break
    if A is None:
        for j in range(w):
            if len(set(grid[i][j] for i in range(h))) == 1:
                a = [r[:j] for r in grid]; b = [r[j+1:] for r in grid]
                if a and b and len(a[0]) == len(b[0]):
                    A, B, orient = a, b, 'col'; break
    cnt = collections.Counter()
    for r in range(len(A)):
        for c in range(len(A[0])):
            if A[r][c] == B[r][c]:
                cnt[A[r][c]] += 1
    bg = cnt.most_common(1)[0][0]
    return [[3 if A[r][c] == B[r][c] else bg for c in range(len(A[0]))] for r in range(len(A))]

import numpy as np
from collections import Counter, defaultdict
import scipy.ndimage as ndimage

def _objs(A,col):
    lab,n=ndimage.label(A==col)
    return [[(int(r),int(c)) for r,c in np.argwhere(lab==i)] for i in range(1,n+1)]

def _canon(o):
    r0,c0=min(r for r,c in o),min(c for r,c in o)
    s=[[0]*(max(c for r,c in o)-c0+1) for _ in range(max(r for r,c in o)-r0+1)]
    for r,cc in o: s[r-r0][cc-c0]=1
    return tuple(map(tuple,s))

def _corner_of(o):
    cells=set(o)
    for r,c in cells:
        hn=int((r,c-1) in cells)+int((r,c+1) in cells)
        vn=int((r-1,c) in cells)+int((r+1,c) in cells)
        if hn and vn and hn+vn==2: return (r,c)
    return None

def transform(grid):
    A=np.array(grid)
    bg=Counter(A.flatten()).most_common(1)[0][0]
    allc={int(c):_objs(A,c) for c in sorted(set(A.flatten())) if c!=bg}
    sing=[(c,allc[c][0]) for c in allc if len(allc[c])==1]
    best=None
    for c,o in sing:
        cr=_corner_of(o)
        if cr is None or len(o)<6: continue
        vert=sum(1 for r,cc in o if cc==cr[1]); horz=sum(1 for r,cc in o if r==cr[0])
        if vert>=3 and horz>=3 and vert+horz-1==len(o):
            if best is None or len(o)>len(best[1]): best=(c,o,cr)
    ac,o,av=best
    shapes=defaultdict(list)
    for c,ol in allc.items():
        for ob in ol: shapes[_canon(ob)].append((c,ob))
    bestscore=None; target=None
    for s,lst in shapes.items():
        if len(lst)!=2: continue
        ds=sorted((min(abs(r-av[0])+abs(cc-av[1]) for r,cc in ob),c,ob) for c,ob in lst)
        score=ds[-1][0]
        if bestscore is None or score<bestscore:
            bestscore=score; target=(ds[-1][1],ds[-1][2])
    tc,to=target
    B=A.copy()
    for r,c in to: B[r][c]=ac
    return B.tolist()

