import numpy as np
from collections import Counter, deque

def components(g, colors):
    g=np.array(g); H,W=g.shape; seen=np.zeros((H,W),bool); comps=[]
    for r in range(H):
        for c in range(W):
            if not seen[r,c] and g[r,c] in colors:
                q=deque([(r,c)]); seen[r,c]=1; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and g[ny,nx] in colors:
                                seen[ny,nx]=1; q.append((ny,nx))
                comps.append(comp)
    return comps

def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    comps=components(g,[c for c in cnt if c!=bg])
    seed=max(comps,key=len)
    single_colors={g[r][c] for comp in comps if len(comp)==1 for r,c in comp}
    mc=single_colors.pop()
    seedcells={(r,c) for comp in comps if len(comp)>1 for r,c in comp}
    rs=[r for r,c in seedcells]; cs=[c for r,c in seedcells]
    ar,ac=(min(rs)+max(rs))//2,(min(cs)+max(cs))//2
    stamp={(r-ar,c-ac):g[r][c] for r,c in seedcells}
    out=[row[:] for row in g]
    for r,c in [c2 for comp in comps if len(comp)==1 for c2 in comp]:
        for (dr,dc),v in stamp.items():
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W: out[nr][nc]=v
    return out

