def find_anchor(g, seedcells):
    sc=sorted(seedcells)
    # line of 3 (horizontal or vertical) whose one end is an 8 -> anchor is middle
    for r,c in sc:
        for dr,dc in ((0,1),(1,0)):
            a,b,m=(r,c),(r+dr,c+dc),(r+2*dr,c+2*dc)
            if b in seedcells and m in seedcells:
                vals=[g[a[0]][a[1]],g[b[0]][b[1]],g[m[0]][m[1]]]
                if 8 in (vals[0],vals[2]) and vals[1]!=8:
                    return b
    return None

def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    comps=components(g,[c for c in cnt if c!=bg])
    seed=max(comps,key=len)
    seedcells={(r,c) for comp in comps if len(comp)>1 for r,c in comp}
    a=find_anchor(g,seedcells)
    if a is None:
        rs=[r for r,c in seedcells]; cs=[c for r,c in seedcells]
        a=((min(rs)+max(rs))//2,(min(cs)+max(cs))//2)
    ar,ac=a
    stamp={(r-ar,c-ac):g[r][c] for r,c in seedcells}
    out=[row[:] for row in g]
    for r,c in [c2 for comp in comps if len(comp)==1 for c2 in comp]:
        for (dr,dc),v in stamp.items():
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W: out[nr][nc]=v
    return out

