        for v in row:
            cnt[v] = cnt.get(v, 0) + 1
    bg = max(cnt, key=cnt.get)
    comps = components(g, [c for c in cnt if c != bg])
    seed = max(comps, key=len)
    seedset = set(seed)
    rs = [p[0] for p in seed]; cs = [p[1] for p in seed]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    ar, ac = (r0+r1)//2, (c0+c1)//2  # anchor = bbox center
    out = [row[:] for row in g]
    # stamp = seed bbox painted as-is at same offset relative to anchor
    for (r, c) in seed:
        out[r][c] = bg
    for (r, c) in seed:
        v = g[r][c]
        rr, cc = r-ar, c-ac
        for (mr, mc) in seed:
            pass
    # markers: every non-bg, non-seed cell
    for r in range(H):
        for c in range(W):
            if g[r][c] != bg and (r, c) not in seedset:
                for (sr, sc) in seed:
                    rr, cc = r + (sr-ar), c + (sc-ac)
                    if 0 <= rr < H and 0 <= cc < W:
